function makeMat(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? true
  });
}

function makeNoiseTexture(size = 96) {
  const data = new Uint8Array(size * size * 3);
  for (let i = 0; i < size * size; i++) {
    const base = 115 + Math.floor(Math.random() * 90);
    data[i * 3] = Math.max(0, Math.min(255, base + Math.floor(Math.random() * 35) - 16));
    data[i * 3 + 1] = Math.max(0, Math.min(255, base + Math.floor(Math.random() * 30) - 12));
    data[i * 3 + 2] = Math.max(0, Math.min(255, base + Math.floor(Math.random() * 45) - 18));
  }
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBFormat);
  tex.needsUpdate = true;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  return tex;
}

function makeVolume({ id, x, w, h, dpth = 0.38, color = COLORS.burnt, noise = false }) {
  const group = new THREE.Group();
  group.name = id;
  const geom = new THREE.BoxGeometry(w, h, dpth);
  const mat = noise
    ? new THREE.MeshBasicMaterial({ map: makeNoiseTexture(), side: THREE.DoubleSide })
    : makeMat(color);
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(0, h / 2, 0);
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    new THREE.LineBasicMaterial({ color: COLORS.edge })
  );
  edges.position.copy(mesh.position);
  group.add(mesh, edges);
  group.position.set(x, 0, 0);
  root.add(group);

  const haloGeom = new THREE.BoxGeometry(w + 0.18, h + 0.18, dpth + 0.12);
  const haloMat = new THREE.LineBasicMaterial({
    color: COLORS.halo,
    transparent: true,
    opacity: 0,
    linewidth: 2
  });
  const halo = new THREE.LineSegments(new THREE.EdgesGeometry(haloGeom), haloMat);
  halo.position.set(x, h / 2, 0);
  root.add(halo);

  return { id, group, mesh, halo, haloMat, x, w, h, dpth, center: new THREE.Vector3(x, h / 2, 0) };
}

