function arrowBetween(start, end, color = COLORS.blue, opts = {}) {
  const group = new THREE.Group();
  const s = start.clone();
  const e = end.clone();
  const dir = e.clone().sub(s);
  const len = dir.length();
  if (len < 1e-6) return group;
  const n = dir.clone().normalize();
  const headLen = opts.headLen ?? 0.16;
  const shaftEnd = e.clone().addScaledVector(n, -headLen);
  const mat = new THREE.LineBasicMaterial({
    color,
    transparent: true,
    opacity: opts.opacity ?? 1
  });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([s, shaftEnd]), mat);
  const coneMat = makeMat(color, { transparent: true, opacity: opts.opacity ?? 1 });
  const cone = new THREE.Mesh(new THREE.ConeGeometry(opts.headRadius ?? 0.055, headLen, 18), coneMat);
  cone.position.copy(e).addScaledVector(n, -headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);
  group.add(line, cone);
  group.userData.materials = [mat, coneMat];
  root.add(group);
  return group;
}

function polyArrow(points, color = COLORS.salmon, opts = {}) {
  const group = new THREE.Group();
  const mat = new THREE.LineBasicMaterial({
    color,
    transparent: true,
    opacity: opts.opacity ?? 1
  });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  group.add(line);
  const p1 = points[points.length - 2], p2 = points[points.length - 1];
  const dir = p2.clone().sub(p1).normalize();
  const headLen = opts.headLen ?? 0.22;
  const coneMat = makeMat(color, { transparent: true, opacity: opts.opacity ?? 1 });
  const cone = new THREE.Mesh(new THREE.ConeGeometry(opts.headRadius ?? 0.075, headLen, 20), coneMat);
  cone.position.copy(p2).addScaledVector(dir, -headLen / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(cone);
  group.userData.materials = [mat, coneMat];
  root.add(group);
  return group;
}

