let t0 = performance.now();
function updateFigureEffects() {
  requestAnimationFrame(updateFigureEffects);
  const now = performance.now();
  const tt = (now - t0) / 1000;
  const active = new Set(phaseToVolumes[passPhase] || []);
  for (const key of Object.keys(volumes)) {
    const v = volumes[key];
    const on = active.has(key);
    v.haloMat.opacity = on ? 0.45 + 0.35 * Math.sin(tt * 7) * Math.sin(tt * 7) : 0;
  }

  for (const key of Object.keys(skipArrows)) {
    const base = 0.9;
    const pulse = key === activeSkipKey ? 0.45 + 0.5 * Math.sin(tt * 8) * Math.sin(tt * 8) : base;
    setArrowOpacity(skipArrows[key], pulse);
  }

  injectionPulse *= 0.92;
  const injOpacity = 0.55 + 0.45 * injectionPulse;
  for (const item of injectionArrows) setArrowOpacity(item.arrow, injOpacity);

  for (const key of Object.keys(indicators)) {
    if (key === passPhase) {
      const op = 0.35 + 0.55 * Math.sin(tt * 9) * Math.sin(tt * 9);
      setArrowOpacity(indicators[key], op);
    }
  }
}
